		return
	}
	replayed, err := h.queries.DeleteRecordExpectedIdempotent(r.Context(), strings.TrimSpace(r.PathValue("objectKey")), strings.TrimSpace(r.PathValue("recordID")), expected, idempotencyKey, h.principal(r))
