		return
	}
	process, ok := operation.Value.(workflowapplication.OpsWorkflowProcessDTO)
	if !ok {
		h.writeError(w, r, http.StatusInternalServerError, "backend.workflow.ops_projection_failed")
		return
	}
	h.writeJSON(w, http.StatusOK, process)
}

