{
  "modules": {
    "crm": {
      "features": {
        "crm_conversion": {
          "requirement": {
            "statement": "qualified 线索按金额阈值转化，大额由总监在 Runtime Workflow 审批，终态原子创建唯一只读客户并通知发起销售。",
            "acceptance": [
              "低于 100000 的负责人线索直接原子转化且重放不产生第二客户。",
              "大于等于 100000 的线索等待销售总监批准或拒绝，非总监不能决定。",
              "批准原子转化并创建唯一客户和通知；拒绝保持 qualified、记录原因和通知且不创建客户。"
            ]
          },
          "objects": {
            "customer": {
              "description": "从已转化线索原子生成且不允许业务角色修改或删除的客户快照。",
              "fields": {
                "amount": "currency!;precision=18;scale=2;rounding=half_even;min=0",
                "company_name": "text!;max_length=200",
                "contact_name": "text;max_length=100",
                "source": "select![website:官网|exhibition:展会|referral:转介绍|cold_call:外呼]",
                "source_lead": "relation!->lead;cardinality=one_to_one;on_delete=restrict"
              },
              "lifecycle_policy": {"mode": "append_only"}
            }
          },
          "actions": {
            "lead.convert_direct": {
              "kind": "record_operation",
              "preconditions": ["status == qualified", "estimated_amount < 100000"],
              "handler": {
                "reason": "小额转化必须在一个事务中 compare-and-set 线索并按来源线索唯一创建客户。",
                "access": {
                  "customer": ["create", "exists"],
                  "lead": ["get_for_update", "conditional_update"]
                }
              }
            },
            "lead.apply_conversion_approval": {
              "kind": "record_operation",
              "preconditions": ["status == qualified", "estimated_amount >= 100000"],
              "handler": {
                "reason": "Workflow 批准分支必须原子 compare-and-set 线索、创建唯一客户并提交收件箱通知意图。",
                "access": {
                  "customer": ["create", "exists"],
                  "lead": ["get_for_update", "conditional_update"]
                },
                "notification_event_types": ["lead.conversion_approved"]
              }
            },
            "lead.apply_conversion_rejection": {
              "kind": "record_operation",
              "input": {"reason": "long_text!"},
              "preconditions": ["status == qualified", "estimated_amount >= 100000"],
              "handler": {
                "reason": "Workflow 拒绝分支必须保持 qualified、原子记录原因且提交收件箱通知意图。",
                "access": {"lead": ["get_for_update", "conditional_update"]},
                "notification_event_types": ["lead.conversion_rejected"]
              }
            }
          },
          "notification_event_types": {
            "lead.conversion_approved": {
              "source": "project",
              "category": "business",
              "default_severity": "info",
              "mandatory_in_app": true,
              "template_key": "lead_conversion_approved",
              "default_locale": "zh_CN",
              "locales": {
                "zh_CN": {
                  "title": "线索转化已批准",
                  "body": "线索「{{company_name}}」已批准并转化为客户。",
                  "action_labels": {"open_lead": "查看线索"}
                }
              },
              "variables": {"company_name": "text!"},
              "actions": {
                "open_lead": {"resource_type": "project_record", "route_key": "sales_my_leads"}
              }
            },
            "lead.conversion_rejected": {
              "source": "project",
              "category": "business",
              "default_severity": "warning",
              "mandatory_in_app": true,
              "template_key": "lead_conversion_rejected",
              "default_locale": "zh_CN",
              "locales": {
                "zh_CN": {
                  "title": "线索转化被拒绝",
                  "body": "线索「{{company_name}}」的转化被拒绝：{{reason}}",
                  "action_labels": {"open_lead": "查看线索"}
                }
              },
              "variables": {"company_name": "text!", "reason": "text!"},
              "actions": {
                "open_lead": {"resource_type": "project_record", "route_key": "sales_my_leads"}
              }
            }
          },
          "workflows": {
            "lead_conversion_approval": {
              "enabled": true,
              "run_as": "crm_workflow_service",
              "trigger": {"type": "manual"},
              "action": {"type": "workflow_graph"},
              "trigger_contract": {"type": "manual", "object_key": "lead"},
              "graph": {
                "nodes": {
                  "submitted": {"type": "trigger"},
                  "director_approval": {
                    "type": "approval",
                    "contract": {
                      "approval": {
                        "mode": "any",
                        "empty_assignee_policy": "fail",
                        "resolvers": [{"type": "role", "role_key": "sales_director"}]
                      }
                    }
                  },
                  "approved_effect": {
                    "type": "action",
                    "contract": {"action": {"action_key": "lead.apply_conversion_approval", "on_error": "fail"}}
                  },
                  "rejected_effect": {
                    "type": "action",
                    "contract": {
                      "action": {
                        "action_key": "lead.apply_conversion_rejection",
                        "input": {"reason": "$workflow.approval_comment"},
                        "on_error": "fail"
                      }
                    }
                  }
                },
                "edges": {
                  "submitted_to_approval": {"source": "submitted", "target": "director_approval"},
                  "approval_to_approved": {"source": "director_approval", "target": "approved_effect", "branch": "approved"},
                  "approval_to_rejected": {"source": "director_approval", "target": "rejected_effect", "branch": "rejected"}
                }
              }
            }
          }
        }
      }
    }
  }
}
